package com.aditya.api; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/order-events") public class ApiController{private final KafkaTemplate<String,String>k; public ApiController(KafkaTemplate<String,String>k){this.k=k;} @PostMapping public String publish(@RequestParam String orderId,@RequestParam String status){k.send("orders.events",orderId,status);return "event queued for "+orderId;}}
